    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture and toss quickly.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Add cream and grilled chicken.\n6. Simmer 10 minutes and serve with rice.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak rice noodles in warm water.\n2. Stir-fry shrimp until pink, set aside.\n3. Scramble eggs in the wok.\n4. Add noodles, tamarind paste, and fish sauce.\n5. Toss with shrimp, bean sprouts.\n6. Garnish with peanuts and lime wedges.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef with taco seasoning.\n2. Warm taco shells in oven.\n3. Dice tomato and shred lettuce.\n4. Assemble tacos with beef, toppings.\n5. Add sour cream and cheese.\n6. Serve with salsa.", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Mix in diced onion, jalapeño, tomato.\n4. Add lime juice and chopped cilantro.\n5. Season with salt.\n6. Serve with tortilla chips.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges set but center jiggles.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onion", Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste in a ladle of broth.\n3. Add dissolved miso back to pot.\n4. Add cubed tofu and wakame.\n5. Heat gently (do not boil).\n6. Garnish with sliced green onion.", AverageRating = 4.2, RatingCount = 6 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

