arguments.file_text:
@page "/recipes"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>Browse Recipes</PageTitle>

<h1>Browse Recipes</h1>
<p>Select a category to explore recipes.</p>

<div class="list-group">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="recipes/@category" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
            @category
            <span class="badge bg-primary rounded-pill">
                @RecipeService.GetRecipesByCategory(category).Count
            </span>
        </a>
    }
</div>

@page "/recipes/{Category}"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@{
    var recipes = RecipeService.GetRecipesByCategory(Category);
}

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;
}

@page "/recipe/{Id:int}"
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.')
                text = text[3..];
            <li>@text</li>
        }
    </ol>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeSharing.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeSharing.Services.RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    title="Rate @star star(s)">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
        @if (selectedRating > 0)
        {
            <span class="text-success ms-2">You rated @selectedRating star(s)!</span>
        }
    </div>
    <small class="text-muted">
        @if (RatingCount > 0)
        {
            <span>Average: @CurrentRating / 5 (@RatingCount ratings)</span>
        }
        else
        {
            <span>No ratings yet — be the first!</span>
        }
    </small>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int selectedRating;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeSharing.Services.RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added successfully.</p>
        <a href="recipes" class="btn btn-primary">Browse Recipes</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            @if (showValidation && string.IsNullOrWhiteSpace(title))
            {
                <div class="text-danger">Title is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Asian">Asian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="American">American</option>
                <option value="Other">Other</option>
            </InputSelect>
            @if (showValidation && string.IsNullOrWhiteSpace(category))
            {
                <div class="text-danger">Category is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="ingredients" class="form-control" rows="4"
                           placeholder="List ingredients separated by commas" />
            @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
            {
                <div class="text-danger">Ingredients are required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="steps" class="form-control" rows="6"
                           placeholder="Describe each step on a new line" />
            @if (showValidation && string.IsNullOrWhiteSpace(steps))
            {
                <div class="text-danger">Steps are required.</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) ||
            string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) ||
            string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        RecipeService.AddRecipe(title, category, ingredients, steps);
        submitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
        showValidation = false;
    }
}

